insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000001',null,encode(sha256(convert_to('{"title":"Sonkás-gombás palacsintabatyu","summary":"Puha palacsinta, krémes töltelék. Egy kis meglepetés a tányéron.","minutes":45,"servings":2,"ingredients":[{"name":"Tojás","amount":"2 db"},{"name":"Tej","amount":"250 ml"},{"name":"Liszt","amount":"120 g"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Konzerv gomba","amount":"80 g"},{"name":"Sajtkrém","amount":"80 g"},{"name":"Hagyma","amount":"½ db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A tojást, tejet, lisztet és csipet sót keverd simára. Kevés olajon süss 4–6 vékony palacsintát.","Az aprított hagymát párold meg, add hozzá a sonkát és a lecsepegtetett gombát. Pirítsd 3–4 percig, majd keverd bele a sajtkrémet.","Töltsd meg a palacsintákat, hajtsd csomagokra. Kiolajozott tálban, 180 °C-on melegítsd át 10–12 percig."],"stepTitles":["Palacsinták sütése","Krémes töltelék","Batyuk hajtogatása és sütése"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Sonkás-gombás palacsintabatyu","summary":"Puha palacsinta, krémes töltelék. Egy kis meglepetés a tányéron.","minutes":45,"servings":2,"ingredients":[{"name":"Tojás","amount":"2 db"},{"name":"Tej","amount":"250 ml"},{"name":"Liszt","amount":"120 g"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Konzerv gomba","amount":"80 g"},{"name":"Sajtkrém","amount":"80 g"},{"name":"Hagyma","amount":"½ db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A tojást, tejet, lisztet és csipet sót keverd simára. Kevés olajon süss 4–6 vékony palacsintát.","Az aprított hagymát párold meg, add hozzá a sonkát és a lecsepegtetett gombát. Pirítsd 3–4 percig, majd keverd bele a sajtkrémet.","Töltsd meg a palacsintákat, hajtsd csomagokra. Kiolajozott tálban, 180 °C-on melegítsd át 10–12 percig."],"stepTitles":["Palacsinták sütése","Krémes töltelék","Batyuk hajtogatása és sütése"]}'::jsonb,array['krémes','tészta'],true,'Morzsa original: batyu') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000002',null,encode(sha256(convert_to('{"title":"Zöldséges pirított rizs","summary":"Egy serpenyő, sok zöldség, egy kis szójaszósz. Hétköznapi kedvenc.","minutes":30,"servings":2,"ingredients":[{"name":"Rizs","amount":"150 g"},{"name":"Zöldségkeverék","amount":"250 g"},{"name":"Tojás","amount":"2 db"},{"name":"Hagyma","amount":"½ db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Szójaszósz","amount":"1–2 ek"},{"name":"Olaj","amount":"2 ek"}],"steps":["Főzd meg a rizst a csomagolás szerint, majd terítsd szét, hogy távozzon a gőze.","Olajon pirítsd meg a hagymát, add hozzá a zöldséget és a fokhagymát. Süsd, amíg a zöldség megpuhul.","Told félre a zöldséget, süsd meg mellette a felvert tojást. Keverd hozzá a rizst és szójaszószt, pirítsd át."],"stepTitles":["Rizs előkészítése","Zöldségek pirítása","Tojás és rizs összeforgatása"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Zöldséges pirított rizs","summary":"Egy serpenyő, sok zöldség, egy kis szójaszósz. Hétköznapi kedvenc.","minutes":30,"servings":2,"ingredients":[{"name":"Rizs","amount":"150 g"},{"name":"Zöldségkeverék","amount":"250 g"},{"name":"Tojás","amount":"2 db"},{"name":"Hagyma","amount":"½ db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Szójaszósz","amount":"1–2 ek"},{"name":"Olaj","amount":"2 ek"}],"steps":["Főzd meg a rizst a csomagolás szerint, majd terítsd szét, hogy távozzon a gőze.","Olajon pirítsd meg a hagymát, add hozzá a zöldséget és a fokhagymát. Süsd, amíg a zöldség megpuhul.","Told félre a zöldséget, süsd meg mellette a felvert tojást. Keverd hozzá a rizst és szójaszószt, pirítsd át."],"stepTitles":["Rizs előkészítése","Zöldségek pirítása","Tojás és rizs összeforgatása"]}'::jsonb,array['gyors','zöldséges','vegetarian'],true,'Morzsa original: rice') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000003',null,encode(sha256(convert_to('{"title":"Krémes sonkás-gombás tészta","summary":"Selymes tejszínes szósz, sonka és gomba. Kész, mire megéhezel.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Konzerv gomba","amount":"80 g"},{"name":"Tejszín","amount":"150 ml"},{"name":"Hagyma","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a tésztát sós vízben a csomagolás szerint. Tegyél félre egy kis főzővizet.","Olajon párold meg a hagymát, pirítsd át a sonkát és a lecsepegtetett gombát.","Öntsd rá a tejszínt, gyöngyöztesd 3–4 percig. Forgasd bele a tésztát, szükség szerint lazítsd főzővízzel."],"stepTitles":["Tésztafőzés","Sonka és gomba pirítása","Krémes szósz összeállítása"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Krémes sonkás-gombás tészta","summary":"Selymes tejszínes szósz, sonka és gomba. Kész, mire megéhezel.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Konzerv gomba","amount":"80 g"},{"name":"Tejszín","amount":"150 ml"},{"name":"Hagyma","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a tésztát sós vízben a csomagolás szerint. Tegyél félre egy kis főzővizet.","Olajon párold meg a hagymát, pirítsd át a sonkát és a lecsepegtetett gombát.","Öntsd rá a tejszínt, gyöngyöztesd 3–4 percig. Forgasd bele a tésztát, szükség szerint lazítsd főzővízzel."],"stepTitles":["Tésztafőzés","Sonka és gomba pirítása","Krémes szósz összeállítása"]}'::jsonb,array['gyors','krémes','tészta'],true,'Morzsa original: pasta') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000004',null,encode(sha256(convert_to('{"title":"Mézes-mustáros csirkecomb","summary":"Aranyszínű combok, édes-pikáns máz és együtt sült krumpli.","minutes":80,"servings":2,"ingredients":[{"name":"Csirkecomb","amount":"2 nagy db"},{"name":"Mustár","amount":"2 ek"},{"name":"Méz","amount":"1 ek"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Krumpli","amount":"500 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A csirkecombot előre olvaszd ki a hűtőben. A sütőt melegítsd 190 °C-ra.","Keverd össze a mustárt, mézet, zúzott fokhagymát, olajat és sót. Kend a combokra.","Tedd tepsibe a darabolt krumplival és hagymával. Lefedve süsd 40 percig, majd fedés nélkül még 20–30 percig.","A comb legvastagabb részében, csontot nem érintve mérve legyen legalább 75 °C. Az idő a comb méretétől függ."],"stepTitles":["Kiolvasztás és előkészítés","Mézes-mustáros pác","Sütés a körettel","Átsültség ellenőrzése"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Mézes-mustáros csirkecomb","summary":"Aranyszínű combok, édes-pikáns máz és együtt sült krumpli.","minutes":80,"servings":2,"ingredients":[{"name":"Csirkecomb","amount":"2 nagy db"},{"name":"Mustár","amount":"2 ek"},{"name":"Méz","amount":"1 ek"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Krumpli","amount":"500 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A csirkecombot előre olvaszd ki a hűtőben. A sütőt melegítsd 190 °C-ra.","Keverd össze a mustárt, mézet, zúzott fokhagymát, olajat és sót. Kend a combokra.","Tedd tepsibe a darabolt krumplival és hagymával. Lefedve süsd 40 percig, majd fedés nélkül még 20–30 percig.","A comb legvastagabb részében, csontot nem érintve mérve legyen legalább 75 °C. Az idő a comb méretétől függ."],"stepTitles":["Kiolvasztás és előkészítés","Mézes-mustáros pác","Sütés a körettel","Átsültség ellenőrzése"]}'::jsonb,array['sült','húsos'],true,'Morzsa original: chicken') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000005',null,encode(sha256(convert_to('{"title":"Szalonnás paprikás krumpli","summary":"Ismerős ízek, kevés mosogatás. Kolbász nélkül is teljes vacsora.","minutes":40,"servings":2,"ingredients":[{"name":"Krumpli","amount":"600 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Szalonna","amount":"80 g"},{"name":"Pirospaprika","amount":"1 tk"},{"name":"Paprika","amount":"1 db"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A szalonnát süsd zsírjára, majd párold meg rajta az aprított hagymát.","Húzd le a tűzről, keverd bele a pirospaprikát. Add hozzá a darabolt krumplit és paprikát.","Önts rá annyi vizet, hogy majdnem ellepje. Sózd, és kis lángon főzd 25–30 percig, amíg a krumpli puha."],"stepTitles":["Szalonnás hagymaalap","Paprikás krumpli összeállítása","Lassú főzés"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Szalonnás paprikás krumpli","summary":"Ismerős ízek, kevés mosogatás. Kolbász nélkül is teljes vacsora.","minutes":40,"servings":2,"ingredients":[{"name":"Krumpli","amount":"600 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Szalonna","amount":"80 g"},{"name":"Pirospaprika","amount":"1 tk"},{"name":"Paprika","amount":"1 db"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A szalonnát süsd zsírjára, majd párold meg rajta az aprított hagymát.","Húzd le a tűzről, keverd bele a pirospaprikát. Add hozzá a darabolt krumplit és paprikát.","Önts rá annyi vizet, hogy majdnem ellepje. Sózd, és kis lángon főzd 25–30 percig, amíg a krumpli puha."],"stepTitles":["Szalonnás hagymaalap","Paprikás krumpli összeállítása","Lassú főzés"]}'::jsonb,array['magyaros','húsos'],true,'Morzsa original: potato') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000006',null,encode(sha256(convert_to('{"title":"Ropogós sonkás wrap","summary":"Krémes belül, ropogós kívül. Egy apró bevásárlásra van szükség.","minutes":15,"servings":2,"ingredients":[{"name":"Tortillalap","amount":"2 db"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Sajtkrém","amount":"60 g"},{"name":"Paprika","amount":"1 db"},{"name":"Joghurt","amount":"2 ek"},{"name":"Mustár","amount":"1 tk"}],"steps":["Keverd össze a joghurtot és mustárt. Kend meg a tortillát sajtkrémmel.","Töltsd meg sonkával és vékony paprikacsíkokkal, locsold meg a joghurtos szósszal.","Hajtsd be az oldalakat, tekerd fel, és száraz serpenyőben pirítsd körbe 3–4 perc alatt."],"stepTitles":["Szósz és tortillalap","Töltelék összeállítása","Wrap hajtogatása és pirítása"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Ropogós sonkás wrap","summary":"Krémes belül, ropogós kívül. Egy apró bevásárlásra van szükség.","minutes":15,"servings":2,"ingredients":[{"name":"Tortillalap","amount":"2 db"},{"name":"Csirkemellsonka","amount":"100 g"},{"name":"Sajtkrém","amount":"60 g"},{"name":"Paprika","amount":"1 db"},{"name":"Joghurt","amount":"2 ek"},{"name":"Mustár","amount":"1 tk"}],"steps":["Keverd össze a joghurtot és mustárt. Kend meg a tortillát sajtkrémmel.","Töltsd meg sonkával és vékony paprikacsíkokkal, locsold meg a joghurtos szósszal.","Hajtsd be az oldalakat, tekerd fel, és száraz serpenyőben pirítsd körbe 3–4 perc alatt."],"stepTitles":["Szósz és tortillalap","Töltelék összeállítása","Wrap hajtogatása és pirítása"]}'::jsonb,array['gyors','húsos'],true,'Morzsa original: tortilla') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000007',null,encode(sha256(convert_to('{"title":"Barackos joghurtpohár","summary":"Friss barack, hűs joghurt, ropogós müzli. Két pohárnyi kedvesség.","minutes":10,"servings":2,"ingredients":[{"name":"Barack","amount":"2 db"},{"name":"Joghurt","amount":"250 g"},{"name":"Müzli","amount":"4 ek"},{"name":"Méz","amount":"1–2 tk"}],"steps":["Mosd meg és kockázd fel a barackot. A joghurtot ízlés szerint édesítsd mézzel.","Rétegezd két pohárba a joghurtot és barackot.","A müzlit közvetlenül tálalás előtt szórd rá, hogy ropogós maradjon."],"stepTitles":["Gyümölcs és joghurt","Poharak rétegezése","Ropogós feltét"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Barackos joghurtpohár","summary":"Friss barack, hűs joghurt, ropogós müzli. Két pohárnyi kedvesség.","minutes":10,"servings":2,"ingredients":[{"name":"Barack","amount":"2 db"},{"name":"Joghurt","amount":"250 g"},{"name":"Müzli","amount":"4 ek"},{"name":"Méz","amount":"1–2 tk"}],"steps":["Mosd meg és kockázd fel a barackot. A joghurtot ízlés szerint édesítsd mézzel.","Rétegezd két pohárba a joghurtot és barackot.","A müzlit közvetlenül tálalás előtt szórd rá, hogy ropogós maradjon."],"stepTitles":["Gyümölcs és joghurt","Poharak rétegezése","Ropogós feltét"]}'::jsonb,array['gyors','édes','vegetarian'],true,'Morzsa original: dessert') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000008',null,encode(sha256(convert_to('{"title":"Krémes almás zabkása","summary":"Meleg reggeli almával és fahéjjal, egy kis lábosból.","minutes":10,"servings":2,"ingredients":[{"name":"Zabpehely","amount":"80 g"},{"name":"Tej","amount":"300 ml"},{"name":"Alma","amount":"1 db"},{"name":"Fahéj","amount":"½ tk"}],"steps":["Reszeld le a megmosott almát. A zabpelyhet és tejet tedd lábosba, add hozzá az alma felét és a fahéjat.","Kis lángon, gyakran keverve főzd 5–7 percig, amíg krémes. Ha túl sűrű, adj hozzá kevés vizet.","Oszd két tálba, tedd rá a maradék almát. Kóstold meg, csak szükség esetén édesítsd."],"stepTitles":["Reszeld le a megmosott almát","Kis lángon, gyakran keverve főzd 5–7 percig, amíg krémes","Oszd két tálba, tedd rá a maradék almát"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Krémes almás zabkása","summary":"Meleg reggeli almával és fahéjjal, egy kis lábosból.","minutes":10,"servings":2,"ingredients":[{"name":"Zabpehely","amount":"80 g"},{"name":"Tej","amount":"300 ml"},{"name":"Alma","amount":"1 db"},{"name":"Fahéj","amount":"½ tk"}],"steps":["Reszeld le a megmosott almát. A zabpelyhet és tejet tedd lábosba, add hozzá az alma felét és a fahéjat.","Kis lángon, gyakran keverve főzd 5–7 percig, amíg krémes. Ha túl sűrű, adj hozzá kevés vizet.","Oszd két tálba, tedd rá a maradék almát. Kóstold meg, csak szükség esetén édesítsd."],"stepTitles":["Reszeld le a megmosott almát","Kis lángon, gyakran keverve főzd 5–7 percig, amíg krémes","Oszd két tálba, tedd rá a maradék almát"]}'::jsonb,array['gyors','vegetarian','édes','téli'],true,'Morzsa original: base-0') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000009',null,encode(sha256(convert_to('{"title":"Paradicsomos lencseragu","summary":"Laktató, növényi vacsora kamrából, puha lencsével.","minutes":30,"servings":2,"ingredients":[{"name":"Konzerv lencse","amount":"400 g"},{"name":"Paradicsomkonzerv","amount":"400 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Az apróra vágott hagymát az olajon párold 5 percig. Add hozzá a zúzott fokhagymát, keverd fél percig.","Öntsd hozzá a paradicsomot és a lecsepegtetett lencsét. Kevés vízzel lazítsd, és kis lángon főzd 15 percig.","Kóstold és sózd. Tálalás előtt hagyd 2 percet állni; kenyérrel vagy főtt rizzsel kínálhatod."],"stepTitles":["Az apróra vágott hagymát az olajon párold 5 percig","Öntsd hozzá a paradicsomot és a lecsepegtetett lencsét","Kóstold és sózd"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Paradicsomos lencseragu","summary":"Laktató, növényi vacsora kamrából, puha lencsével.","minutes":30,"servings":2,"ingredients":[{"name":"Konzerv lencse","amount":"400 g"},{"name":"Paradicsomkonzerv","amount":"400 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Az apróra vágott hagymát az olajon párold 5 percig. Add hozzá a zúzott fokhagymát, keverd fél percig.","Öntsd hozzá a paradicsomot és a lecsepegtetett lencsét. Kevés vízzel lazítsd, és kis lángon főzd 15 percig.","Kóstold és sózd. Tálalás előtt hagyd 2 percet állni; kenyérrel vagy főtt rizzsel kínálhatod."],"stepTitles":["Az apróra vágott hagymát az olajon párold 5 percig","Öntsd hozzá a paradicsomot és a lecsepegtetett lencsét","Kóstold és sózd"]}'::jsonb,array['vegan','vegetarian','gyors'],true,'Morzsa original: base-1') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000010',null,encode(sha256(convert_to('{"title":"Sütőben sült zöldségek","summary":"Színes tepsi ropogós szélű zöldségekkel.","minutes":40,"servings":2,"ingredients":[{"name":"Krumpli","amount":"400 g"},{"name":"Sárgarépa","amount":"2 db"},{"name":"Hagyma","amount":"1 db"},{"name":"Paprika","amount":"1 db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"½ tk"}],"steps":["Melegítsd a sütőt 200 °C-ra. A megtisztított krumplit és répát vágd 2 cm-es darabokra, a hagymát és paprikát nagyobb szeletekre.","Forgasd össze olajjal és sóval, majd terítsd egy rétegben sütőpapíros tepsire. Ne zsúfold össze.","Süsd 30–35 percig, félidőben forgasd át. Akkor kész, ha a krumpli belül puha, a szélek aranybarnák."],"stepTitles":["Melegítsd a sütőt 200 °C-ra","Forgasd össze olajjal és sóval, majd terítsd egy rétegben sütőpapíros tepsire","Süsd 30–35 percig, félidőben forgasd át"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Sütőben sült zöldségek","summary":"Színes tepsi ropogós szélű zöldségekkel.","minutes":40,"servings":2,"ingredients":[{"name":"Krumpli","amount":"400 g"},{"name":"Sárgarépa","amount":"2 db"},{"name":"Hagyma","amount":"1 db"},{"name":"Paprika","amount":"1 db"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"½ tk"}],"steps":["Melegítsd a sütőt 200 °C-ra. A megtisztított krumplit és répát vágd 2 cm-es darabokra, a hagymát és paprikát nagyobb szeletekre.","Forgasd össze olajjal és sóval, majd terítsd egy rétegben sütőpapíros tepsire. Ne zsúfold össze.","Süsd 30–35 percig, félidőben forgasd át. Akkor kész, ha a krumpli belül puha, a szélek aranybarnák."],"stepTitles":["Melegítsd a sütőt 200 °C-ra","Forgasd össze olajjal és sóval, majd terítsd egy rétegben sütőpapíros tepsire","Süsd 30–35 percig, félidőben forgasd át"]}'::jsonb,array['vegan','vegetarian','téli'],true,'Morzsa original: base-2') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000011',null,encode(sha256(convert_to('{"title":"Citromos csicseriborsó-saláta","summary":"Friss, ropogós saláta főzés nélkül.","minutes":15,"servings":2,"ingredients":[{"name":"Konzerv csicseriborsó","amount":"400 g"},{"name":"Uborka","amount":"½ db"},{"name":"Paradicsom","amount":"2 db"},{"name":"Citrom","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Öblítsd és alaposan csepegtesd le a csicseriborsót. Az uborkát és paradicsomot mosd meg, vágd kis kockákra.","A citromlevet keverd össze az olajjal és egy csipet sóval. Forgasd a zöldségekhez és csicseriborsóhoz.","Pihentesd 5 percig, majd kóstold meg. Hűtve vagy azonnal tálalható."],"stepTitles":["Öblítsd és alaposan csepegtesd le a csicseriborsót","A citromlevet keverd össze az olajjal és egy csipet sóval","Pihentesd 5 percig, majd kóstold meg"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Citromos csicseriborsó-saláta","summary":"Friss, ropogós saláta főzés nélkül.","minutes":15,"servings":2,"ingredients":[{"name":"Konzerv csicseriborsó","amount":"400 g"},{"name":"Uborka","amount":"½ db"},{"name":"Paradicsom","amount":"2 db"},{"name":"Citrom","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Öblítsd és alaposan csepegtesd le a csicseriborsót. Az uborkát és paradicsomot mosd meg, vágd kis kockákra.","A citromlevet keverd össze az olajjal és egy csipet sóval. Forgasd a zöldségekhez és csicseriborsóhoz.","Pihentesd 5 percig, majd kóstold meg. Hűtve vagy azonnal tálalható."],"stepTitles":["Öblítsd és alaposan csepegtesd le a csicseriborsót","A citromlevet keverd össze az olajjal és egy csipet sóval","Pihentesd 5 percig, majd kóstold meg"]}'::jsonb,array['gyors','vegan','vegetarian','nyári'],true,'Morzsa original: base-3') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000012',null,encode(sha256(convert_to('{"title":"Sajtos-tojásos melegszendvics","summary":"Serpenyős mentőöv egy sűrű napra.","minutes":15,"servings":2,"ingredients":[{"name":"Kenyér","amount":"4 szelet"},{"name":"Tojás","amount":"2 db"},{"name":"Sajt","amount":"60 g"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A tojást verd fel a sóval. Két kenyérszeletre tedd a reszelt sajtot, fedd le a másik két szelettel.","Mártsd a szendvicsek mindkét oldalát röviden a tojásba. A vajat olvaszd fel közepes lángon egy serpenyőben.","Süsd oldalanként 3–4 percig. A kenyér legyen aranybarna, a tojás teljesen megsült, a sajt olvadt."],"stepTitles":["A tojást verd fel a sóval","Mártsd a szendvicsek mindkét oldalát röviden a tojásba","Süsd oldalanként 3–4 percig"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Sajtos-tojásos melegszendvics","summary":"Serpenyős mentőöv egy sűrű napra.","minutes":15,"servings":2,"ingredients":[{"name":"Kenyér","amount":"4 szelet"},{"name":"Tojás","amount":"2 db"},{"name":"Sajt","amount":"60 g"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A tojást verd fel a sóval. Két kenyérszeletre tedd a reszelt sajtot, fedd le a másik két szelettel.","Mártsd a szendvicsek mindkét oldalát röviden a tojásba. A vajat olvaszd fel közepes lángon egy serpenyőben.","Süsd oldalanként 3–4 percig. A kenyér legyen aranybarna, a tojás teljesen megsült, a sajt olvadt."],"stepTitles":["A tojást verd fel a sóval","Mártsd a szendvicsek mindkét oldalát röviden a tojásba","Süsd oldalanként 3–4 percig"]}'::jsonb,array['gyors','vegetarian'],true,'Morzsa original: base-4') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000013',null,encode(sha256(convert_to('{"title":"Banános palacsinta","summary":"Puha, kicsi palacsinták két főnek.","minutes":20,"servings":2,"ingredients":[{"name":"Banán","amount":"1 nagy db"},{"name":"Tojás","amount":"2 db"},{"name":"Liszt","amount":"60 g"},{"name":"Tej","amount":"80 ml"},{"name":"Olaj","amount":"1 tk"}],"steps":["A banánt villával törd pépesre. Keverd bele a tojásokat, lisztet és tejet; sűrű, kanalazható tésztát kell kapnod.","Olajozz ki egy tapadásmentes serpenyőt. Közepes lángon, kis adagokban süsd a palacsintákat 2–3 percig.","Amikor a szélek megszilárdulnak, óvatosan fordítsd meg. Süsd még 1–2 percig, amíg a közepe is átsül."],"stepTitles":["A banánt villával törd pépesre","Olajozz ki egy tapadásmentes serpenyőt","Amikor a szélek megszilárdulnak, óvatosan fordítsd meg"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Banános palacsinta","summary":"Puha, kicsi palacsinták két főnek.","minutes":20,"servings":2,"ingredients":[{"name":"Banán","amount":"1 nagy db"},{"name":"Tojás","amount":"2 db"},{"name":"Liszt","amount":"60 g"},{"name":"Tej","amount":"80 ml"},{"name":"Olaj","amount":"1 tk"}],"steps":["A banánt villával törd pépesre. Keverd bele a tojásokat, lisztet és tejet; sűrű, kanalazható tésztát kell kapnod.","Olajozz ki egy tapadásmentes serpenyőt. Közepes lángon, kis adagokban süsd a palacsintákat 2–3 percig.","Amikor a szélek megszilárdulnak, óvatosan fordítsd meg. Süsd még 1–2 percig, amíg a közepe is átsül."],"stepTitles":["A banánt villával törd pépesre","Olajozz ki egy tapadásmentes serpenyőt","Amikor a szélek megszilárdulnak, óvatosan fordítsd meg"]}'::jsonb,array['gyors','vegetarian','édes'],true,'Morzsa original: base-5') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000014',null,encode(sha256(convert_to('{"title":"Egyszerű kakaós brownie","summary":"Szaftos, jól szeletelhető süti az irodába is.","minutes":35,"servings":2,"ingredients":[{"name":"Vaj","amount":"100 g"},{"name":"Cukor","amount":"120 g"},{"name":"Tojás","amount":"2 db"},{"name":"Liszt","amount":"80 g"},{"name":"Kakaópor","amount":"40 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A sütőt melegítsd 175 °C-ra. Bélelj ki egy kb. 20 × 20 cm-es formát sütőpapírral. Az olvasztott, langyos vajat keverd el a cukorral.","Keverd bele a tojásokat, majd a lisztet, kakaót és sót. Csak addig keverd, amíg egynemű, és simítsd a formába.","Süsd 20–25 percig. A szél legyen szilárd, középen a fogpiszkálóra nedves morzsa tapadhat, nyers tészta ne. Teljes kihűlés után szeleteld."],"stepTitles":["A sütőt melegítsd 175 °C-ra","Keverd bele a tojásokat, majd a lisztet, kakaót és sót","Süsd 20–25 percig"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Egyszerű kakaós brownie","summary":"Szaftos, jól szeletelhető süti az irodába is.","minutes":35,"servings":2,"ingredients":[{"name":"Vaj","amount":"100 g"},{"name":"Cukor","amount":"120 g"},{"name":"Tojás","amount":"2 db"},{"name":"Liszt","amount":"80 g"},{"name":"Kakaópor","amount":"40 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A sütőt melegítsd 175 °C-ra. Bélelj ki egy kb. 20 × 20 cm-es formát sütőpapírral. Az olvasztott, langyos vajat keverd el a cukorral.","Keverd bele a tojásokat, majd a lisztet, kakaót és sót. Csak addig keverd, amíg egynemű, és simítsd a formába.","Süsd 20–25 percig. A szél legyen szilárd, középen a fogpiszkálóra nedves morzsa tapadhat, nyers tészta ne. Teljes kihűlés után szeleteld."],"stepTitles":["A sütőt melegítsd 175 °C-ra","Keverd bele a tojásokat, majd a lisztet, kakaót és sót","Süsd 20–25 percig"]}'::jsonb,array['vegetarian','édes'],true,'Morzsa original: base-6') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000015',null,encode(sha256(convert_to('{"title":"Fahéjas almás muffin","summary":"Könnyen szállítható, egyszerű sütemény.","minutes":35,"servings":2,"ingredients":[{"name":"Alma","amount":"2 db"},{"name":"Liszt","amount":"180 g"},{"name":"Cukor","amount":"80 g"},{"name":"Tojás","amount":"2 db"},{"name":"Tej","amount":"100 ml"},{"name":"Olaj","amount":"60 ml"},{"name":"Sütőpor","amount":"1 tk"},{"name":"Fahéj","amount":"1 tk"}],"steps":["Melegítsd a sütőt 180 °C-ra, tegyél papírkapszlit 12 muffinmélyedésbe. A megmosott almát vágd apró kockákra.","Keverd össze a lisztet, sütőport és fahéjat. Másik tálban verd össze a tojást, cukrot, tejet és olajat, majd röviden forgasd bele a lisztet és almát.","Oszd a formákba, legfeljebb háromnegyedig töltve. Süsd 20–25 percig; tűpróbával ellenőrizd, majd rácson hűtsd ki."],"stepTitles":["Melegítsd a sütőt 180 °C-ra, tegyél papírkapszlit 12 muffinmélyedésbe","Keverd össze a lisztet, sütőport és fahéjat","Oszd a formákba, legfeljebb háromnegyedig töltve"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Fahéjas almás muffin","summary":"Könnyen szállítható, egyszerű sütemény.","minutes":35,"servings":2,"ingredients":[{"name":"Alma","amount":"2 db"},{"name":"Liszt","amount":"180 g"},{"name":"Cukor","amount":"80 g"},{"name":"Tojás","amount":"2 db"},{"name":"Tej","amount":"100 ml"},{"name":"Olaj","amount":"60 ml"},{"name":"Sütőpor","amount":"1 tk"},{"name":"Fahéj","amount":"1 tk"}],"steps":["Melegítsd a sütőt 180 °C-ra, tegyél papírkapszlit 12 muffinmélyedésbe. A megmosott almát vágd apró kockákra.","Keverd össze a lisztet, sütőport és fahéjat. Másik tálban verd össze a tojást, cukrot, tejet és olajat, majd röviden forgasd bele a lisztet és almát.","Oszd a formákba, legfeljebb háromnegyedig töltve. Süsd 20–25 percig; tűpróbával ellenőrizd, majd rácson hűtsd ki."],"stepTitles":["Melegítsd a sütőt 180 °C-ra, tegyél papírkapszlit 12 muffinmélyedésbe","Keverd össze a lisztet, sütőport és fahéjat","Oszd a formákba, legfeljebb háromnegyedig töltve"]}'::jsonb,array['vegetarian','édes','téli'],true,'Morzsa original: base-7') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000016',null,encode(sha256(convert_to('{"title":"Fokhagymás gombás tészta","summary":"Pirított gomba és tészta könnyű szószban.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Gomba","amount":"250 g"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a tésztát sós vízben, a csomagolás ideje szerint. Leszűrés előtt tegyél félre 150 ml főzővizet.","A felszeletelt gombát forró olajon, egy rétegben pirítsd 6–8 percig. Amikor aranybarna, add hozzá az aprított fokhagymát és keverd fél percig.","Forgasd bele a tésztát. Kevés főzővízzel lazítsd, és 1–2 percig keverve forrald össze. Kóstold meg és sózd."],"stepTitles":["Főzd a tésztát sós vízben, a csomagolás ideje szerint","A felszeletelt gombát forró olajon, egy rétegben pirítsd 6–8 percig","Forgasd bele a tésztát"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Fokhagymás gombás tészta","summary":"Pirított gomba és tészta könnyű szószban.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Gomba","amount":"250 g"},{"name":"Fokhagyma","amount":"2 gerezd"},{"name":"Olaj","amount":"2 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a tésztát sós vízben, a csomagolás ideje szerint. Leszűrés előtt tegyél félre 150 ml főzővizet.","A felszeletelt gombát forró olajon, egy rétegben pirítsd 6–8 percig. Amikor aranybarna, add hozzá az aprított fokhagymát és keverd fél percig.","Forgasd bele a tésztát. Kevés főzővízzel lazítsd, és 1–2 percig keverve forrald össze. Kóstold meg és sózd."],"stepTitles":["Főzd a tésztát sós vízben, a csomagolás ideje szerint","A felszeletelt gombát forró olajon, egy rétegben pirítsd 6–8 percig","Forgasd bele a tésztát"]}'::jsonb,array['gyors','vegan','vegetarian'],true,'Morzsa original: base-8') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000017',null,encode(sha256(convert_to('{"title":"Paradicsomos mozzarellás tészta","summary":"Friss paradicsommal, olvadó sajttal.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Paradicsom","amount":"3 db"},{"name":"Mozzarella","amount":"125 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd meg a tésztát sós vízben, és tegyél félre kevés főzővizet. A paradicsomot kockázd fel.","Olajon futtasd meg az aprított fokhagymát. Add hozzá a paradicsomot, sózd, és főzd 8–10 percig.","Forgasd bele a tésztát, lazítsd főzővízzel. Vedd le a tűzről, keverd hozzá a tépett mozzarellát, és rögtön tálald."],"stepTitles":["Főzd meg a tésztát sós vízben, és tegyél félre kevés főzővizet","Olajon futtasd meg az aprított fokhagymát","Forgasd bele a tésztát, lazítsd főzővízzel"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Paradicsomos mozzarellás tészta","summary":"Friss paradicsommal, olvadó sajttal.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Paradicsom","amount":"3 db"},{"name":"Mozzarella","amount":"125 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd meg a tésztát sós vízben, és tegyél félre kevés főzővizet. A paradicsomot kockázd fel.","Olajon futtasd meg az aprított fokhagymát. Add hozzá a paradicsomot, sózd, és főzd 8–10 percig.","Forgasd bele a tésztát, lazítsd főzővízzel. Vedd le a tűzről, keverd hozzá a tépett mozzarellát, és rögtön tálald."],"stepTitles":["Főzd meg a tésztát sós vízben, és tegyél félre kevés főzővizet","Olajon futtasd meg az aprított fokhagymát","Forgasd bele a tésztát, lazítsd főzővízzel"]}'::jsonb,array['gyors','vegetarian','nyári'],true,'Morzsa original: base-9') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000018',null,encode(sha256(convert_to('{"title":"Brokkolis sajtos krémleves","summary":"Lágy, zöld leves kevés hozzávalóból.","minutes":25,"servings":2,"ingredients":[{"name":"Brokkoli","amount":"400 g"},{"name":"Krumpli","amount":"1 db"},{"name":"Hagyma","amount":"½ db"},{"name":"Sajt","amount":"60 g"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát olajon párold meg. Add hozzá az apróra vágott krumplit, a brokkoli rózsáit és megtisztított szárát.","Önts rá kb. 600 ml vizet. Sózd, és főzd 15 percig, amíg minden puha.","Botmixerrel turmixold simára. Keverd bele a reszelt sajtot, kis lángon olvaszd fel; ne forrald erősen."],"stepTitles":["A hagymát olajon párold meg","Önts rá kb","Botmixerrel turmixold simára"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Brokkolis sajtos krémleves","summary":"Lágy, zöld leves kevés hozzávalóból.","minutes":25,"servings":2,"ingredients":[{"name":"Brokkoli","amount":"400 g"},{"name":"Krumpli","amount":"1 db"},{"name":"Hagyma","amount":"½ db"},{"name":"Sajt","amount":"60 g"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát olajon párold meg. Add hozzá az apróra vágott krumplit, a brokkoli rózsáit és megtisztított szárát.","Önts rá kb. 600 ml vizet. Sózd, és főzd 15 percig, amíg minden puha.","Botmixerrel turmixold simára. Keverd bele a reszelt sajtot, kis lángon olvaszd fel; ne forrald erősen."],"stepTitles":["A hagymát olajon párold meg","Önts rá kb","Botmixerrel turmixold simára"]}'::jsonb,array['gyors','vegetarian','téli'],true,'Morzsa original: base-10') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000019',null,encode(sha256(convert_to('{"title":"Répa-gyömbér krémleves","summary":"Melengető leves, friss gyömbérrel.","minutes":30,"servings":2,"ingredients":[{"name":"Sárgarépa","amount":"500 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Gyömbér","amount":"1 cm-es darab"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát aprítsd fel, a répát karikázd. Olajon párold a hagymát 4 percig, majd add hozzá a reszelt gyömbért.","Add hozzá a répát és kb. 650 ml vizet. Sózd, és főzd 20 percig, amíg a répa teljesen puha.","Botmixerrel turmixold simára. Ha túl sűrű, apránként adj hozzá vizet, és kóstold újra."],"stepTitles":["A hagymát aprítsd fel, a répát karikázd","Add hozzá a répát és kb","Botmixerrel turmixold simára"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Répa-gyömbér krémleves","summary":"Melengető leves, friss gyömbérrel.","minutes":30,"servings":2,"ingredients":[{"name":"Sárgarépa","amount":"500 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Gyömbér","amount":"1 cm-es darab"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát aprítsd fel, a répát karikázd. Olajon párold a hagymát 4 percig, majd add hozzá a reszelt gyömbért.","Add hozzá a répát és kb. 650 ml vizet. Sózd, és főzd 20 percig, amíg a répa teljesen puha.","Botmixerrel turmixold simára. Ha túl sűrű, apránként adj hozzá vizet, és kóstold újra."],"stepTitles":["A hagymát aprítsd fel, a répát karikázd","Add hozzá a répát és kb","Botmixerrel turmixold simára"]}'::jsonb,array['gyors','vegan','vegetarian','téli'],true,'Morzsa original: base-11') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000020',null,encode(sha256(convert_to('{"title":"Tonhalas kukoricás tésztasaláta","summary":"Előre elkészíthető ebéd dobozba.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Tonhalkonzerv","amount":"160 g"},{"name":"Konzerv kukorica","amount":"150 g"},{"name":"Joghurt","amount":"100 g"},{"name":"Citrom","amount":"½ db"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A tésztát főzd meg a csomagolás szerint. Szűrd le és terítsd szét, hogy gyorsan kihűljön.","Csepegtesd le a tonhalat és a kukoricát. Keverd össze a joghurtot a citrom levével és kevés sóval.","Forgasd össze a hideg tésztát a tonhallal, kukoricával és öntettel. Tedd hűtőbe; ne hagyd szobahőmérsékleten állni."],"stepTitles":["A tésztát főzd meg a csomagolás szerint","Csepegtesd le a tonhalat és a kukoricát","Forgasd össze a hideg tésztát a tonhallal, kukoricával és öntettel"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Tonhalas kukoricás tésztasaláta","summary":"Előre elkészíthető ebéd dobozba.","minutes":25,"servings":2,"ingredients":[{"name":"Tészta","amount":"180 g"},{"name":"Tonhalkonzerv","amount":"160 g"},{"name":"Konzerv kukorica","amount":"150 g"},{"name":"Joghurt","amount":"100 g"},{"name":"Citrom","amount":"½ db"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A tésztát főzd meg a csomagolás szerint. Szűrd le és terítsd szét, hogy gyorsan kihűljön.","Csepegtesd le a tonhalat és a kukoricát. Keverd össze a joghurtot a citrom levével és kevés sóval.","Forgasd össze a hideg tésztát a tonhallal, kukoricával és öntettel. Tedd hűtőbe; ne hagyd szobahőmérsékleten állni."],"stepTitles":["A tésztát főzd meg a csomagolás szerint","Csepegtesd le a tonhalat és a kukoricát","Forgasd össze a hideg tésztát a tonhallal, kukoricával és öntettel"]}'::jsonb,array['gyors','nyári'],true,'Morzsa original: base-12') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000021',null,encode(sha256(convert_to('{"title":"Citromos csirkemell rizzsel","summary":"Egyszerű, friss ízű serpenyős vacsora.","minutes":30,"servings":2,"ingredients":[{"name":"Csirkemell","amount":"300 g"},{"name":"Rizs","amount":"150 g"},{"name":"Citrom","amount":"½ db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a rizst a csomagolás szerint. A csirkemellet vágd egyenletes, 2 cm-es kockákra, sózd.","Közepesen forró olajon süsd a csirkét 8–10 percig, gyakran forgatva. Add hozzá az aprított fokhagymát az utolsó percben.","Locsold meg citromlével, adj hozzá 2 evőkanál vizet. A legvastagabb húsdarab közepe érje el a 75 °C-ot. Tálald a rizzsel."],"stepTitles":["Főzd a rizst a csomagolás szerint","Közepesen forró olajon süsd a csirkét 8–10 percig, gyakran forgatva","Locsold meg citromlével, adj hozzá 2 evőkanál vizet"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Citromos csirkemell rizzsel","summary":"Egyszerű, friss ízű serpenyős vacsora.","minutes":30,"servings":2,"ingredients":[{"name":"Csirkemell","amount":"300 g"},{"name":"Rizs","amount":"150 g"},{"name":"Citrom","amount":"½ db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["Főzd a rizst a csomagolás szerint. A csirkemellet vágd egyenletes, 2 cm-es kockákra, sózd.","Közepesen forró olajon süsd a csirkét 8–10 percig, gyakran forgatva. Add hozzá az aprított fokhagymát az utolsó percben.","Locsold meg citromlével, adj hozzá 2 evőkanál vizet. A legvastagabb húsdarab közepe érje el a 75 °C-ot. Tálald a rizzsel."],"stepTitles":["Főzd a rizst a csomagolás szerint","Közepesen forró olajon süsd a csirkét 8–10 percig, gyakran forgatva","Locsold meg citromlével, adj hozzá 2 evőkanál vizet"]}'::jsonb,array['gyors'],true,'Morzsa original: base-13') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000022',null,encode(sha256(convert_to('{"title":"Spenótos rántotta","summary":"Gyors reggeli vagy könnyű vacsora.","minutes":10,"servings":2,"ingredients":[{"name":"Tojás","amount":"4 db"},{"name":"Spenót","amount":"100 g"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A megmosott spenótot olvasztott vajon fonnyaszd 1–2 percig. A tojást verd fel a sóval.","Öntsd a tojást a spenótra, és közepesen alacsony lángon, spatulával lassan keverve süsd.","Amikor a tojás már nem folyós, de még puha, vedd le a tűzről. Azonnal tálald."],"stepTitles":["A megmosott spenótot olvasztott vajon fonnyaszd 1–2 percig","Öntsd a tojást a spenótra, és közepesen alacsony lángon, spatulával lassan ke","Amikor a tojás már nem folyós, de még puha, vedd le a tűzről"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Spenótos rántotta","summary":"Gyors reggeli vagy könnyű vacsora.","minutes":10,"servings":2,"ingredients":[{"name":"Tojás","amount":"4 db"},{"name":"Spenót","amount":"100 g"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A megmosott spenótot olvasztott vajon fonnyaszd 1–2 percig. A tojást verd fel a sóval.","Öntsd a tojást a spenótra, és közepesen alacsony lángon, spatulával lassan keverve süsd.","Amikor a tojás már nem folyós, de még puha, vedd le a tűzről. Azonnal tálald."],"stepTitles":["A megmosott spenótot olvasztott vajon fonnyaszd 1–2 percig","Öntsd a tojást a spenótra, és közepesen alacsony lángon, spatulával lassan ke","Amikor a tojás már nem folyós, de még puha, vedd le a tűzről"]}'::jsonb,array['gyors','vegetarian'],true,'Morzsa original: base-14') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000023',null,encode(sha256(convert_to('{"title":"Zöldséges kuszkusz","summary":"Tízperces alap, ami a készletedhez igazítható.","minutes":15,"servings":2,"ingredients":[{"name":"Kuszkusz","amount":"150 g"},{"name":"Paprika","amount":"1 db"},{"name":"Uborka","amount":"½ db"},{"name":"Citrom","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A kuszkuszt enyhén sózd, és öntsd fel a csomagoláson megadott mennyiségű forró vízzel. Fedd le 5 percre.","Kockázd fel a megmosott paprikát és uborkát. A kuszkuszt villával lazítsd fel.","Forgasd össze a zöldségekkel, olajjal és citromlével. Kóstold és igazítsd a sót."],"stepTitles":["A kuszkuszt enyhén sózd, és öntsd fel a csomagoláson megadott mennyiségű forr","Kockázd fel a megmosott paprikát és uborkát","Forgasd össze a zöldségekkel, olajjal és citromlével"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Zöldséges kuszkusz","summary":"Tízperces alap, ami a készletedhez igazítható.","minutes":15,"servings":2,"ingredients":[{"name":"Kuszkusz","amount":"150 g"},{"name":"Paprika","amount":"1 db"},{"name":"Uborka","amount":"½ db"},{"name":"Citrom","amount":"½ db"},{"name":"Olaj","amount":"1 ek"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A kuszkuszt enyhén sózd, és öntsd fel a csomagoláson megadott mennyiségű forró vízzel. Fedd le 5 percre.","Kockázd fel a megmosott paprikát és uborkát. A kuszkuszt villával lazítsd fel.","Forgasd össze a zöldségekkel, olajjal és citromlével. Kóstold és igazítsd a sót."],"stepTitles":["A kuszkuszt enyhén sózd, és öntsd fel a csomagoláson megadott mennyiségű forr","Kockázd fel a megmosott paprikát és uborkát","Forgasd össze a zöldségekkel, olajjal és citromlével"]}'::jsonb,array['gyors','vegan','vegetarian'],true,'Morzsa original: base-15') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000024',null,encode(sha256(convert_to('{"title":"Ropogós csicseriborsó","summary":"Fűszeres feltét salátára vagy kis sós harapnivaló.","minutes":35,"servings":2,"ingredients":[{"name":"Konzerv csicseriborsó","amount":"400 g"},{"name":"Olaj","amount":"1 ek"},{"name":"Pirospaprika","amount":"½ tk"},{"name":"Só","amount":"½ tk"}],"steps":["A sütőt melegítsd 200 °C-ra. A csicseriborsót öblítsd le, majd konyharuhán alaposan szárítsd meg.","Forgasd össze az olajjal, sóval és paprikával. Terítsd egy rétegben sütőpapírra.","Süsd 25–30 percig, félidőben rázd át. Akkor jó, ha kívül száraz és ropogós; tálalásig ne fedd le."],"stepTitles":["A sütőt melegítsd 200 °C-ra","Forgasd össze az olajjal, sóval és paprikával","Süsd 25–30 percig, félidőben rázd át"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Ropogós csicseriborsó","summary":"Fűszeres feltét salátára vagy kis sós harapnivaló.","minutes":35,"servings":2,"ingredients":[{"name":"Konzerv csicseriborsó","amount":"400 g"},{"name":"Olaj","amount":"1 ek"},{"name":"Pirospaprika","amount":"½ tk"},{"name":"Só","amount":"½ tk"}],"steps":["A sütőt melegítsd 200 °C-ra. A csicseriborsót öblítsd le, majd konyharuhán alaposan szárítsd meg.","Forgasd össze az olajjal, sóval és paprikával. Terítsd egy rétegben sütőpapírra.","Süsd 25–30 percig, félidőben rázd át. Akkor jó, ha kívül száraz és ropogós; tálalásig ne fedd le."],"stepTitles":["A sütőt melegítsd 200 °C-ra","Forgasd össze az olajjal, sóval és paprikával","Süsd 25–30 percig, félidőben rázd át"]}'::jsonb,array['vegan','vegetarian'],true,'Morzsa original: base-16') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000025',null,encode(sha256(convert_to('{"title":"Tepsis sajtos krumpli","summary":"Puha krumpli, aranybarna sajtos tető.","minutes":50,"servings":2,"ingredients":[{"name":"Krumpli","amount":"600 g"},{"name":"Tejszín","amount":"150 ml"},{"name":"Sajt","amount":"100 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"½ tk"}],"steps":["Melegítsd a sütőt 190 °C-ra. A meghámozott krumplit szeleteld vékonyan. Vajazz ki egy kisebb sütőtálat.","Rétegezd a krumplit kevés sóval és fokhagymával. Öntsd rá a tejszínt, és fedd le alufóliával.","Süsd 30 percig, majd szórd rá a sajtot. Fedés nélkül süsd még 15 percig, amíg a krumpli puha és a sajt aranybarna."],"stepTitles":["Melegítsd a sütőt 190 °C-ra","Rétegezd a krumplit kevés sóval és fokhagymával","Süsd 30 percig, majd szórd rá a sajtot"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Tepsis sajtos krumpli","summary":"Puha krumpli, aranybarna sajtos tető.","minutes":50,"servings":2,"ingredients":[{"name":"Krumpli","amount":"600 g"},{"name":"Tejszín","amount":"150 ml"},{"name":"Sajt","amount":"100 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Vaj","amount":"10 g"},{"name":"Só","amount":"½ tk"}],"steps":["Melegítsd a sütőt 190 °C-ra. A meghámozott krumplit szeleteld vékonyan. Vajazz ki egy kisebb sütőtálat.","Rétegezd a krumplit kevés sóval és fokhagymával. Öntsd rá a tejszínt, és fedd le alufóliával.","Süsd 30 percig, majd szórd rá a sajtot. Fedés nélkül süsd még 15 percig, amíg a krumpli puha és a sajt aranybarna."],"stepTitles":["Melegítsd a sütőt 190 °C-ra","Rétegezd a krumplit kevés sóval és fokhagymával","Süsd 30 percig, majd szórd rá a sajtot"]}'::jsonb,array['vegetarian','téli'],true,'Morzsa original: base-17') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000026',null,encode(sha256(convert_to('{"title":"Joghurtos uborkasaláta","summary":"Hűs köret, öt perc aktív munkával.","minutes":10,"servings":2,"ingredients":[{"name":"Uborka","amount":"1 db"},{"name":"Joghurt","amount":"200 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Só","amount":"¼ tk"}],"steps":["Az uborkát mosd meg és reszeld le. Enyhén sózd, pihentesd 5 percig, majd a felesleges levet nyomkodd ki.","Keverd a joghurtba a finomra reszelt fokhagymát. Forgasd hozzá az uborkát.","Kóstold meg, ha kell, sózd. Tálalásig tartsd hűtőben."],"stepTitles":["Az uborkát mosd meg és reszeld le","Keverd a joghurtba a finomra reszelt fokhagymát","Kóstold meg, ha kell, sózd"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Joghurtos uborkasaláta","summary":"Hűs köret, öt perc aktív munkával.","minutes":10,"servings":2,"ingredients":[{"name":"Uborka","amount":"1 db"},{"name":"Joghurt","amount":"200 g"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Só","amount":"¼ tk"}],"steps":["Az uborkát mosd meg és reszeld le. Enyhén sózd, pihentesd 5 percig, majd a felesleges levet nyomkodd ki.","Keverd a joghurtba a finomra reszelt fokhagymát. Forgasd hozzá az uborkát.","Kóstold meg, ha kell, sózd. Tálalásig tartsd hűtőben."],"stepTitles":["Az uborkát mosd meg és reszeld le","Keverd a joghurtba a finomra reszelt fokhagymát","Kóstold meg, ha kell, sózd"]}'::jsonb,array['gyors','vegetarian','nyári'],true,'Morzsa original: base-18') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000027',null,encode(sha256(convert_to('{"title":"Sütőtökös rizottó","summary":"Krémes, őszi-téli rizses egytálétel.","minutes":40,"servings":2,"ingredients":[{"name":"Sütőtök","amount":"300 g"},{"name":"Rizottórizs","amount":"160 g"},{"name":"Hagyma","amount":"½ db"},{"name":"Vaj","amount":"20 g"},{"name":"Sajt","amount":"40 g"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A sütőtököt hámozd meg és vágd kis kockákra. A hagymát a vaj felén párold meg, majd add hozzá a rizst és keverd 1 percig.","Add hozzá a tököt. Enyhén sózott forró vizet adagolj hozzá merőkanalanként; időnként keverd, a következő adagot akkor add, amikor az előzőt felszívta.","Kb. 20–25 perc után a rizs legyen puha, de ne szétfőtt. Vedd le a tűzről, keverd bele a maradék vajat és sajtot; ha kell, lazítsd vízzel."],"stepTitles":["A sütőtököt hámozd meg és vágd kis kockákra","Add hozzá a tököt","Kb"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Sütőtökös rizottó","summary":"Krémes, őszi-téli rizses egytálétel.","minutes":40,"servings":2,"ingredients":[{"name":"Sütőtök","amount":"300 g"},{"name":"Rizottórizs","amount":"160 g"},{"name":"Hagyma","amount":"½ db"},{"name":"Vaj","amount":"20 g"},{"name":"Sajt","amount":"40 g"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A sütőtököt hámozd meg és vágd kis kockákra. A hagymát a vaj felén párold meg, majd add hozzá a rizst és keverd 1 percig.","Add hozzá a tököt. Enyhén sózott forró vizet adagolj hozzá merőkanalanként; időnként keverd, a következő adagot akkor add, amikor az előzőt felszívta.","Kb. 20–25 perc után a rizs legyen puha, de ne szétfőtt. Vedd le a tűzről, keverd bele a maradék vajat és sajtot; ha kell, lazítsd vízzel."],"stepTitles":["A sütőtököt hámozd meg és vágd kis kockákra","Add hozzá a tököt","Kb"]}'::jsonb,array['vegetarian','téli'],true,'Morzsa original: base-19') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000028',null,encode(sha256(convert_to('{"title":"Zabos banánkeksz","summary":"Egyszerű, puha keksz érett banánból.","minutes":25,"servings":2,"ingredients":[{"name":"Banán","amount":"2 érett db"},{"name":"Zabpehely","amount":"120 g"},{"name":"Fahéj","amount":"½ tk"}],"steps":["Melegítsd a sütőt 180 °C-ra. A banánt törd össze villával, keverd bele a zabpelyhet és fahéjat.","Pihentesd 5 percig. Kanalazz 10–12 kis halmot sütőpapírra, lapítsd le őket, mert maguktól nem terülnek szét.","Süsd 15–18 percig, amíg a szélek enyhén barnulnak. Hagyd a tepsin hűlni 10 percig; ezek puha, nem ropogós kekszek."],"stepTitles":["Melegítsd a sütőt 180 °C-ra","Pihentesd 5 percig","Süsd 15–18 percig, amíg a szélek enyhén barnulnak"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Zabos banánkeksz","summary":"Egyszerű, puha keksz érett banánból.","minutes":25,"servings":2,"ingredients":[{"name":"Banán","amount":"2 érett db"},{"name":"Zabpehely","amount":"120 g"},{"name":"Fahéj","amount":"½ tk"}],"steps":["Melegítsd a sütőt 180 °C-ra. A banánt törd össze villával, keverd bele a zabpelyhet és fahéjat.","Pihentesd 5 percig. Kanalazz 10–12 kis halmot sütőpapírra, lapítsd le őket, mert maguktól nem terülnek szét.","Süsd 15–18 percig, amíg a szélek enyhén barnulnak. Hagyd a tepsin hűlni 10 percig; ezek puha, nem ropogós kekszek."],"stepTitles":["Melegítsd a sütőt 180 °C-ra","Pihentesd 5 percig","Süsd 15–18 percig, amíg a szélek enyhén barnulnak"]}'::jsonb,array['vegan','vegetarian','édes','gyors'],true,'Morzsa original: base-20') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000029',null,encode(sha256(convert_to('{"title":"Paradicsomos babragu","summary":"Kamrabarát, tartalmas vacsora hús nélkül.","minutes":25,"servings":2,"ingredients":[{"name":"Konzerv bab","amount":"400 g"},{"name":"Paradicsomkonzerv","amount":"400 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Pirospaprika","amount":"½ tk"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát vágd apróra, olajon párold 5 percig. Add hozzá az aprított fokhagymát, keverd fél percig.","Húzd le röviden a tűzről, szórd bele a pirospaprikát, majd öntsd hozzá a paradicsomot és a leöblített babot.","Kis lángon főzd 15 percig. Kóstold és sózd, kenyérrel vagy rizzsel tálalhatod."],"stepTitles":["A hagymát vágd apróra, olajon párold 5 percig","Húzd le röviden a tűzről, szórd bele a pirospaprikát, majd öntsd hozzá a para","Kis lángon főzd 15 percig"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Paradicsomos babragu","summary":"Kamrabarát, tartalmas vacsora hús nélkül.","minutes":25,"servings":2,"ingredients":[{"name":"Konzerv bab","amount":"400 g"},{"name":"Paradicsomkonzerv","amount":"400 g"},{"name":"Hagyma","amount":"1 db"},{"name":"Fokhagyma","amount":"1 gerezd"},{"name":"Olaj","amount":"1 ek"},{"name":"Pirospaprika","amount":"½ tk"},{"name":"Só","amount":"ízlés szerint"}],"steps":["A hagymát vágd apróra, olajon párold 5 percig. Add hozzá az aprított fokhagymát, keverd fél percig.","Húzd le röviden a tűzről, szórd bele a pirospaprikát, majd öntsd hozzá a paradicsomot és a leöblített babot.","Kis lángon főzd 15 percig. Kóstold és sózd, kenyérrel vagy rizzsel tálalhatod."],"stepTitles":["A hagymát vágd apróra, olajon párold 5 percig","Húzd le röviden a tűzről, szórd bele a pirospaprikát, majd öntsd hozzá a para","Kis lángon főzd 15 percig"]}'::jsonb,array['vegan','vegetarian','gyors'],true,'Morzsa original: base-21') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000030',null,encode(sha256(convert_to('{"title":"Gombás sajtos omlett","summary":"Lágy belsejű omlett, pirított töltelékkel.","minutes":20,"servings":2,"ingredients":[{"name":"Tojás","amount":"4 db"},{"name":"Gomba","amount":"150 g"},{"name":"Sajt","amount":"50 g"},{"name":"Vaj","amount":"15 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A gombát szeleteld fel, a vaj felén pirítsd 5–6 percig, majd tedd félre. Verd fel a tojásokat sóval.","A maradék vajon, közepesen alacsony lángon süss két külön omlettet. A szélekről húzd be a megkötött tojást, hogy a folyós rész lefolyhasson.","Amikor a tojás már majdnem megszilárdult, tedd az egyik felére a gombát és sajtot. Hajtsd félbe, és melegítsd még 1 percig."],"stepTitles":["A gombát szeleteld fel, a vaj felén pirítsd 5–6 percig, majd tedd félre","A maradék vajon, közepesen alacsony lángon süss két külön omlettet","Amikor a tojás már majdnem megszilárdult, tedd az egyik felére a gombát és sa"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Gombás sajtos omlett","summary":"Lágy belsejű omlett, pirított töltelékkel.","minutes":20,"servings":2,"ingredients":[{"name":"Tojás","amount":"4 db"},{"name":"Gomba","amount":"150 g"},{"name":"Sajt","amount":"50 g"},{"name":"Vaj","amount":"15 g"},{"name":"Só","amount":"1 csipet"}],"steps":["A gombát szeleteld fel, a vaj felén pirítsd 5–6 percig, majd tedd félre. Verd fel a tojásokat sóval.","A maradék vajon, közepesen alacsony lángon süss két külön omlettet. A szélekről húzd be a megkötött tojást, hogy a folyós rész lefolyhasson.","Amikor a tojás már majdnem megszilárdult, tedd az egyik felére a gombát és sajtot. Hajtsd félbe, és melegítsd még 1 percig."],"stepTitles":["A gombát szeleteld fel, a vaj felén pirítsd 5–6 percig, majd tedd félre","A maradék vajon, közepesen alacsony lángon süss két külön omlettet","Amikor a tojás már majdnem megszilárdult, tedd az egyik felére a gombát és sa"]}'::jsonb,array['gyors','vegetarian'],true,'Morzsa original: base-22') on conflict(id) do nothing;
insert into public.recipe_documents(id,owner_id,content_hash,content,tags,published,source) values('10000000-0000-4000-8000-000000000031',null,encode(sha256(convert_to('{"title":"Kókuszos tejberizs","summary":"Lassan főtt, krémes desszert két tálkába.","minutes":35,"servings":2,"ingredients":[{"name":"Rizs","amount":"100 g"},{"name":"Tej","amount":"400 ml"},{"name":"Kókuszreszelék","amount":"2 ek"},{"name":"Cukor","amount":"1 ek"}],"steps":["A rizst öblítsd át, majd tedd lábosba a tejjel és 100 ml vízzel. Közepes lángon kezdd melegíteni.","Amikor gyöngyözik, vedd kis lángra. Gyakran keverve főzd 25–30 percig, amíg puha és krémes; szükség esetén adj hozzá kevés tejet.","Keverd bele a cukrot és kókuszreszeléket. Pihentesd 5 percig; melegen vagy lehűtve tálald."],"stepTitles":["A rizst öblítsd át, majd tedd lábosba a tejjel és 100 ml vízzel","Amikor gyöngyözik, vedd kis lángra","Keverd bele a cukrot és kókuszreszeléket"]}'::jsonb::text,'UTF8')),'hex'),'{"title":"Kókuszos tejberizs","summary":"Lassan főtt, krémes desszert két tálkába.","minutes":35,"servings":2,"ingredients":[{"name":"Rizs","amount":"100 g"},{"name":"Tej","amount":"400 ml"},{"name":"Kókuszreszelék","amount":"2 ek"},{"name":"Cukor","amount":"1 ek"}],"steps":["A rizst öblítsd át, majd tedd lábosba a tejjel és 100 ml vízzel. Közepes lángon kezdd melegíteni.","Amikor gyöngyözik, vedd kis lángra. Gyakran keverve főzd 25–30 percig, amíg puha és krémes; szükség esetén adj hozzá kevés tejet.","Keverd bele a cukrot és kókuszreszeléket. Pihentesd 5 percig; melegen vagy lehűtve tálald."],"stepTitles":["A rizst öblítsd át, majd tedd lábosba a tejjel és 100 ml vízzel","Amikor gyöngyözik, vedd kis lángra","Keverd bele a cukrot és kókuszreszeléket"]}'::jsonb,array['vegetarian','édes'],true,'Morzsa original: base-23') on conflict(id) do nothing;
